//! Trained decision parameters (generated by harness/es_tune.py / harness/league_train.py).
//! W: multipliers on hand-set constants (1.0 = hand value). TARGET / FIGHT: linear weights of
//! the camp-target and fight scorers (0.0 = off). ROUTER: use weights/router.bin (offline RL)
//! on complex turns. EPSILON: exploration rate for RL data games (0 in submitted builds).

pub const GEM: usize = 0;
pub const GOLD: usize = 1;
pub const DIST: usize = 2;
pub const CLEAR: usize = 3;
pub const STRENGTH_DISCOUNT: usize = 4;
pub const REWARD: usize = 5;
pub const HYSTERESIS: usize = 6;
pub const SHARED_SMALL: usize = 7;
pub const OPENING_DIST: usize = 8;
pub const EN_DETOUR: usize = 9;
pub const EN_CLEAR: usize = 10;
pub const FIGHT_MARGIN: usize = 11;
pub const RETREAT_HP: usize = 12;
pub const AGGRESSION: usize = 13;
pub const RECALL_GOLD: usize = 14;
pub const TRIBUTE_MIN: usize = 15;
pub const TRIBUTE_MAX: usize = 16;
pub const ASSIST_HP: usize = 17;
pub const N: usize = 18;

pub const W: [f32; N] = [0.8767, 0.8706, 1.4981, 1.0030, 0.6848, 1.3941, 1.6960, 0.9492, 1.2156, 0.9570, 1.1999, 1.3028, 1.2043, 1.0134, 0.9485, 0.6669, 0.7462, 2.1408];

/// Camp-target scorer: score *= exp(TARGET . phi), phi = [gems/100, gold/100, dist/20,
/// clear/50, respawn eta/50, other claimants, damage taken/hp, our bag/100, emblems/5, round/1000].
pub const T_N: usize = 10;
pub const TARGET: [f32; T_N] = [0.0; T_N];
/// Fight scorer: advantage *= exp(FIGHT . psi), psi = [hp frac, enemy hp frac, allies near,
/// enemies near, we ranged, enemy ranged, bag/100, spawn dist/20, 1].
pub const F_N: usize = 9;
pub const FIGHT: [f32; F_N] = [0.0; F_N];
pub const ROUTER: bool = false;
pub const EPSILON: f32 = 0.0;
